import os, re, subprocess, json, sys

ROOT = "/mnt/raid/home/yangshuangning/vuln_variant_search/experiments/clairvoyant_variant_search/runs/C6/public/snapshots/s02"
OUT = os.path.join(os.environ["TMPDIR"], "scan_results.txt")

HELPERS = re.compile(r'\b(pskb_expand_head|skb_realloc_headroom|skb_cow|skb_cow_head|skb_linearize|skb_linearize_cow|pskb_trim|pskb_trim_rcsum|skb_copy_expand_head)\s*\(')

# patterns indicating derivation of pointer/offset into skb data
DERIVE_PTR = re.compile(r'(\w+)\s*=\s*(?:\([^{;=]*\)\s*)?(?:skb(?:_dev)?_header_pointer|ip_hdr|ipv6_hdr|tcp_hdr|udp_hdr|icmp_hdr|icmp6_hdr|igmp_hdr|arp_hdr|dccp_hdr|sctp_hdr|gre_hdr|ipip_hdr|ipv6_skip_exthdr[^;]*|eth_hdr|vlan_hdr|skb_tail_pointer|skb_transport_header|skb_network_header|skb_mac_header|skb_reset|skb_get)\s*\(')
DERIVE_DATA = re.compile(r'(\w+)\s*=\s*(?:skb->data|skb->head)\b')
DERIVE_ADD = re.compile(r'(\w+)\s*=\s*(?:[^;=]*?\bskb->data\s*\+|[^;=]*?\+\s*skb->data)\b')
ACCESSOR_USE = re.compile(r'\b(ip_hdr|ipv6_hdr|tcp_hdr|udp_hdr|icmp_hdr|icmp6_hdr|igmp_hdr|arp_hdr|dccp_hdr|sctp_hdr|gre_hdr|eth_hdr|vlan_hdr|skb_network_header|skb_transport_header|skb_mac_header|skb_tail_pointer)\s*\(\s*(\w+)\s*\)')
OFF_DERIVE = re.compile(r'(\w+)\s*=\s*([A-Za-z0-9_]+)\s*-\s*skb->data\b')

files = []
for base in ("net", "drivers/net"):
    for dirpath, dirnames, filenames in os.walk(os.path.join(ROOT, base)):
        for fn in filenames:
            if fn.endswith((".c", ".h")):
                files.append(os.path.join(dirpath, fn))

results = []
for path in files:
    try:
        with open(path, "r", errors="replace") as f:
            lines = f.readlines()
    except OSError:
        continue
    rel = os.path.relpath(path, ROOT)
    # find function boundaries crudely: a line starting with '}' at col 0 ends func
    func_start = 0
    func_name = None
    func_lines = []
    def flush():
        global func_name, func_lines, func_start
        if func_name is None:
            return
        text = "".join(func_lines)
        helper_ms = list(HELPERS.finditer(text))
        if not helper_ms:
            return
        # compute base offset
        for hm in helper_ms:
            hline = func_start + text[:hm.start()].count("\n")
            for i in range(func_start, hline):
                ln = lines[i]
                m = DERIVE_PTR.search(ln) or DERIVE_DATA.search(ln) or DERIVE_ADD.search(ln)
                if m:
                    ptrvar = m.group(1)
                    # search use after helper line until func end
                    end = func_start + len(func_lines)
                    for j in range(hline+1, end):
                        ln2 = lines[j]
                        if re.search(r'\b' + re.escape(ptrvar) + r'\b', ln2) and not re.search(r'\b' + re.escape(ptrvar) + r'\s*=', ln2.strip()[:len(ptrvar)+1]):
                            # exclude immediate re-assignment lines
                            results.append((rel, hline+1, ptrvar, func_name, j+1, ln.strip()[:100]))
                            break
    # simpler: iterate over functions
    i = 0
    n = len(lines)
    while i < n:
        if re.match(r'^\}', lines[i]):
            # function ended; body from start to i
            if func_name is not None:
                text = "".join(lines[func_start:i+1])
                for hm in HELPERS.finditer(text):
                    hline = func_start + text[:hm.start()].count("\n")
                    for k in range(func_start, hline):
                        ln = lines[k]
                        m = DERIVE_PTR.search(ln) or DERIVE_DATA.search(ln) or DERIVE_ADD.search(ln)
                        if m:
                            ptrvar = m.group(1)
                            for j in range(hline+1, i+1):
                                ln2 = lines[j]
                                if re.search(r'\b' + re.escape(ptrvar) + r'\b', ln2):
                                    if re.match(r'\s*(' + re.escape(ptrvar) + r')\s*=[^=]', ln2):
                                        break  # reassigned, safe
                                    results.append((rel, hline+1, ptrvar, func_name, j+1, ln2.strip()[:120]))
                                    break
            func_name = None
        m = re.match(r'^(?:static\s+)?(?:inline\s+)?(?:[A-Za-z_][\w\s\*]*?)\b(\w+)\s*\([^;]*$', lines[i])
        if m and not lines[i].strip().endswith(";"):
            func_name = m.group(1)
            func_start = i
        i += 1

with open(OUT, "w") as f:
    for r in results:
        f.write("%s:%d helper-call; var=%s func=%s first-use-line=%d: %s\n" % r)
print("candidates:", len(results))
