for dirpath, dirs, files in os.walk(ROOT):
    rel = os.path.relpath(dirpath, ROOT)
    if not (rel.startswith("net") or rel.startswith("drivers/net")):
        continue
    for fn in files:
        if not fn.endswith(".c"): continue
        path = os.path.join(dirpath, fn)
        try: src = open(path, encoding='utf-8', errors='replace').read()
        except OSError: continue
        lines = src.split("\n")
        for li, line in enumerate(lines):
            if not HELP.search(line): continue
            fstart = None
            for back in range(li, max(-1, li-500), -1):
                l = lines[back]
                if l.endswith("{") and not re.match(r"^\s*(case|if|for|while|else|do|switch|\.|})", l):
                    fstart = back; break
            if fstart is None: continue
            fend = brace_block(lines, fstart)
            assigns = {}
            for k in range(fstart, li):
                l = lines[k]
                for dm in re.finditer(r"\b(" + IDENT + r")\s*=\s*([^;]+);", l):
                    name, rhs = dm.group(1), dm.group(2)
                    if not re.match(r"^[A-Za-z_][A-Za-z0-9_]*$", name): continue
                    if DERIVE_RE.search(rhs) or re.search(r"\bskb->data\b", rhs) or re.search(r"\bskb_shinfo\s*\(\s*\w+\s*\)", rhs):
                        if name not in assigns:
                            assigns[name] = (k+1, l.strip()[:130])
            if not assigns: continue
            for name, (k0, decl) in assigns.items():
                uses = []
                for k in range(li, fend):
                    if re.search(r"\b" + re.escape(name) + r"\b", lines[k]) and not re.match(r"^\s*\**" + re.escape(name) + r"\s*=[^=]", lines[k]):
                        uses.append((k+1, lines[k].strip()[:130]))
                if uses:
                    out.append({
                        "file": os.path.relpath(path, ROOT),
                        "call_line": li + 1, "call": line.strip()[:110],
                        "fn_line": fstart + 1, "fn": lines[fstart].strip()[:90],
                        "var": name, "decl_line": k0, "decl": decl,
                        "uses": uses[:8],
                    })
json.dump(out, open(os.environ["TMPDIR"] + "/scan_out.json", "w"), indent=1)
print("candidates:", len(out))
