input.command:
cat > "$TMPDIR/scan.py" <<'PYEOF'
import re, os, sys, subprocess

root = "/mnt/raid/home/yangshuangning/vuln_variant_search/experiments/clairvoyant_variant_search/runs/C6/public/snapshots/s02"
helper_re = re.compile(r'\b(pskb_expand_head|skb_realloc_headroom|skb_cow|skb_cow_head|skb_linearize|skb_linearize_cow|pskb_trim|pskb_trim_rcsum|pskb_carve|skb_copy_expand_head)\s*\(')

# patterns that derive a pointer/offset from skb data area
derive_re = re.compile(
    r'\b([a-zA-Z_][a-zA-Z0-9_]*)\s*=\s*(?:\([^)]*\*\)\s*)?'
    r'(skb[a-zA-Z0-9_]*->[a-z_]+|skb[a-zA-Z0-9_]*'
    r'(?:_header_pointer|_network_header|_transport_header|_mac_header|_vlan_header|_push|_pull|_put|_tail_pointer|_data|_reset_transport_header|_reset_network_header|_set_network_header|_set_transport_header|_reset_mac_header|_set_mac_header)\s*\([^)]*\)'
    r'|[a-zA-Z_][a-zA-Z0-9_]*\s*\+\s*[a-zA-Z0-9_>.+\- ]*offset[a-zA-Z0-9_]*'
    r')'
)

def functions_of(path):
    with open(path, 'r', errors='replace') as f:
        lines = f.readlines()
    funcs = []  # (name, start, end)
    cur = None
    for i, ln in enumerate(lines):
        m = re.match(r'^(?:static\s+)?(?:inline\s+)?(?:const\s+)?[A-Za-z_][A-Za-z0-9_ \*]*?\**\s*\**([A-Za-z_][A-Za-z0-9_]*)\s*\(', ln)
        if cur is None and m and not ln.strip().startswith(('#','//','*')) and not re.match(r'^\s*(if|for|while|switch|return|sizeof)', ln):
            cur = [m.group(1), i, None, 0]
        if cur:
            cur[3] += len(re.findall(r'\{', ln)) - len(re.findall(r'\}', ln))
            if cur[3] <= 0 and '{' not in ''.join(lines[cur[1]:i+1]) and i > cur[1] + 40:
                cur = None
            elif cur[3] == 0 and '{' in ''.join(lines[cur[1]:i+1]):
                cur[2] = i
                funcs.append(tuple(cur))
                cur = None
    if cur and cur[2] is None:
        cur[2] = len(lines)-1
        funcs.append(tuple(cur))
    return funcs, lines

results = []
files = subprocess.run(['grep','-rl','-E',
  r'\b(pskb_expand_head|skb_realloc_headroom|skb_cow|skb_linearize|pskb_trim|pskb_carve|skb_copy_expand_head)\b',
  'net/','drivers/net/'], capture_output=True, text=True, cwd=root).stdout.split()

for rel in files:
    path = os.path.join(root, rel)
    try:
        funcs, lines = functions_of(path)
    except Exception:
        continue
    for name, s, e, _ in funcs:
        body = lines[s:e+1]
        helper_lines = [j for j,ln in enumerate(body) if helper_re.search(ln) and not ln.strip().startswith(('*','//','#','/*'))]
        if not helper_lines:
            continue
        # find derived vars before helper line, used after
        derived = {}
        for j, ln in enumerate(body):
            if j in helper_lines: break
            for m in derive_re.finditer(ln):
                v = m.group(1)
                if v in ('if','for','while','return','sizeof','else'): continue
                derived.setdefault(v, (s+j+1, ln.rstrip()))
        if not derived:
            continue
        for h in helper_lines:
            after = body[h+1:]
            for v,(dl,dline) in sorted(derived.items()):
                used = [k for k,ln in enumerate(after) if re.search(r'\b'+re.escape(v)+r'\b', ln)]
                if used:
                    results.append((rel, s+h+1, v, dl, name, lines[s+h].strip()))

for r in results:
    print(f"{r[0]}:{r[1]}\tfunc={r[4]}\tvar={r[2]}\tsaved@{r[3]}\thelper={r[5][:90]}")
print(f"TOTAL {len(results)}", file=sys.stderr)
PYEOF
python3 "$TMPDIR/scan.py" > "$TMPDIR/candidates.txt" 2> "$TMPDIR/scan.err"; cat "$TMPDIR/scan.err"; wc -l "$TMPDIR/candidates.txt"

