import re, os, sys, subprocess, json

ROOT = sys.argv[1]
HELPERS = ["pskb_expand_head","skb_realloc_headroom","skb_cow_head","skb_cow","skb_linearize_cow","skb_linearize","pskb_trim_rcsum","pskb_trim","pskb_carve","skb_copy_expand_head"]

files = subprocess.run(["bash","-c",
  "grep -rl -E '\\b(pskb_expand_head|skb_realloc_headroom|skb_cow|skb_cow_head|skb_linearize|skb_linearize_cow|pskb_trim|pskb_trim_rcsum|pskb_carve|skb_copy_expand_head) *\\(' %s/net %s/drivers/net --include='*.c' 2>/dev/null" % (ROOT,ROOT)],
  capture_output=True,text=True).stdout.split()

HDR_DERIVE = re.compile(r"""
 ^\s*(?:[A-Za-z_][\w\s\*]*?\s+[\*]?)?(?P<var>[A-Za-z_]\w*)\s*=\s*(?:
      (?P<hdrfn>skb_header_pointer|skb_network_header|skb_mac_header|skb_transport_header|ip_hdr|ipv6_hdr|tcp_hdr|udp_hdr|sctp_hdr|icmp_hdr|icmp6_hdr|igmp_hdr|arp_hdr|eth_hdr|vlan_hdr|gre_hdr|ipv6_hopopt_hdr|ipv6_opt_hdr|ipv6_rt_hdr|ipv6_exthdr|dccp_hdr|ah_hdr|esp_hdr|skb_tail_pointer|skb_push|skb_pull|skb_trim|skb->head|skb_headlen)
    | \([^)]*\)\s*skb->data
    | skb->data
    | .*->data\b
    | .*->head\b
    | .*skb.*->data
 )""", re.X)

def strip_comments(text):
    out=[];i=0;n=len(text);state=0
    while i<n:
        c=text[i]
        if state==0:
            if c=='/' and i+1<n and text[i+1]=='/':
                state=1;i+=2;continue
            if c=='/' and i+1<n and text[i+1]=='*':
                state=2;i+=2;out.append(' ');continue
            if c=='"':
                state=3;out.append(c);i+=1;continue
            if c=="'":
                state=4;out.append(c);i+=1;continue
            out.append(c);i+=1
        elif state==1:
            if c=='\n': state=0;out.append(c)
            i+=1
        elif state==2:
            if c=='*' and i+1<n and text[i+1]=='/': state=0;i+=2;out.append(' ');continue
            if c=='\n': out.append('\n')
            i+=1
        elif state==3:
            if c=='\\': i+=2;continue
            if c=='"': state=0;out.append('"');i+=1;continue
            if c=='\n': state=0;out.append('\n')
            i+=1
        elif state==4:
            if c=='\\': i+=2;continue
            if c=="'": state=0;out.append("'");i+=1;continue
            if c=='\n': state=0;out.append('\n')
            i+=1
    return ''.join(out)

def funcs(lines):
    n=len(lines); i=0
    while i<n:
        if lines[i].startswith('{'):
            start=i; depth=0
            j=i
            while j<n:
                depth += lines[j].count('{')-lines[j].count('}')
                if depth<=0 and j>i: break
                j+=1
            yield start, j, lines[start:j+1]
            i=j+1
        else:
            i+=1

HELPER_RE = {h: re.compile(r'\b'+h+r'\s*\(') for h in HELPERS}

results=[]
for f in files:
    try: text=open(f,errors='replace').read()
    except: continue
    text=strip_comments(text)
    lines=text.split('\n')
    for (fs,fe,body) in funcs(lines):
        btext='\n'.join(body)
        # find helper calls
        callpos=[]
        for h,rx in HELPER_RE.items():
            for m in rx.finditer(btext):
                callpos.append((m.start(),h))
        if not callpos: continue
        # find pointer saves before first call
        flat=btext
        # line index map
        def lineno(pos): return fs + flat[:pos].count('\n')+1
        # collect candidate pointer variables: any "var = <expr referencing ->data or header accessor>"
        assign_re = re.compile(r'\b([A-Za-z_]\w*)\s*=\s*([^;]+);')
        saved={}  # var -> (pos, line, expr)
        for m in assign_re.finditer(flat):
            var,expr=m.group(1),m.group(2).strip()
            if re.search(r'->data\b|->head\b|\b(skb_header_pointer|skb_network_header|skb_mac_header|skb_transport_header|ip_hdr|ipv6_hdr|tcp_hdr|udp_hdr|sctp_hdr|icmp_hdr|icmp6_hdr|igmp_hdr|arp_hdr|eth_hdr|vlan_hdr|gre_hdr|dccp_hdr|ipv6_hopopt_hdr|ipv6_exthdr|ipv6_opt_hdr|ipv6_rt_hdr|skb_tail_pointer)\s*\(', expr):
                saved.setdefault(var,[]).append((m.start(),lineno(m.start()),expr))
        if not saved: continue
        for (cpos,h) in callpos:
            for var,saves in saved.items():
                for (spos,sline,expr) in saves:
                    if spos<cpos:
                        # use after call: occurrences of var after cpos that are not plain reassignment
                        for um in re.finditer(r'\b'+re.escape(var)+r'\b', flat[cpos:]):
                            apos=cpos+um.start()
                            am=re.match(r'\s*=[^=]', flat[apos+len(var):])
                            # check preceding char not part of identifier (regex \b handles)
                            if flat[apos+len(var):apos+len(var)+1]=='=' and flat[apos+len(var)+1:apos+len(var)+2]!='=':
                                continue  # reassignment
                            ctx=flat[max(0,apos-40):apos+60].replace('\n',' ')
                            results.append(dict(file=os.path.relpath(f,ROOT), func_line=fs+1, helper=h,
                                helper_line=lineno(cpos), var=var, save_line=sline, expr=expr[:90],
                                use_line=lineno(apos), ctx=ctx))
                            break
                        break  # only first save per var
                    break
print(json.dumps(results,indent=1))
